import{_ as a,o as t,c as r,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Providers & Fallback","description":"","frontmatter":{"title":"Providers & Fallback"},"headers":[],"relativePath":"concepts/providers-fallback.md","filePath":"concepts/providers-fallback.md"}'),o={name:"concepts/providers-fallback.md"};function l(s,e,n,i,c,p){return t(),r("div",null,[...e[0]||(e[0]=[d('<blockquote><p>🚧 Wingport is in active development. The API described here is the v0.1 design. Star the repo to follow along, or join the early access list.</p></blockquote><h1 id="providers-fallback" tabindex="-1">Providers &amp; Fallback <a class="header-anchor" href="#providers-fallback" aria-label="Permalink to &quot;Providers &amp; Fallback&quot;">​</a></h1><h2 id="supported-providers-v0-1-target" tabindex="-1">Supported providers (v0.1 target) <a class="header-anchor" href="#supported-providers-v0-1-target" aria-label="Permalink to &quot;Supported providers (v0.1 target)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Text generation</th><th>Streaming</th><th>Notes</th></tr></thead><tbody><tr><td>Anthropic</td><td>✅</td><td>✅</td><td>Claude models</td></tr><tr><td>OpenAI</td><td>✅</td><td>✅</td><td>GPT models</td></tr><tr><td>Google</td><td>✅</td><td>✅</td><td>Gemini models</td></tr><tr><td>OpenRouter</td><td><span class="VPBadge warning">Planned</span></td><td><span class="VPBadge warning">Planned</span></td><td>Use as a meta-provider</td></tr><tr><td>On-device</td><td><span class="VPBadge warning">Planned</span></td><td><span class="VPBadge warning">Planned</span></td><td>Offline fallback via local models</td></tr></tbody></table><p>All providers are normalized to one request/response shape. Provider-specific parameters pass through a <code>providerOptions</code> escape hatch.</p><h2 id="fallback" tabindex="-1">Fallback <a class="header-anchor" href="#fallback" aria-label="Permalink to &quot;Fallback&quot;">​</a></h2><p>With <code>fallback: true</code>, a request that fails with a retryable provider error (<code>429</code>, <code>5xx</code>, overload) automatically re-routes to the next provider in your <code>providers</code> array that serves a compatible model. The SDK sees one stream; the handoff is invisible to your UI.</p><p>Fallback events are recorded in <code>wingport_usage.provider_used</code>, so you can see exactly how often your primary is failing over.</p><h2 id="multimodal-planned" tabindex="-1">Multimodal <span class="VPBadge warning">Planned</span> <a class="header-anchor" href="#multimodal-planned" aria-label="Permalink to &quot;Multimodal &lt;span class=&quot;VPBadge warning&quot;&gt;Planned&lt;/span&gt;&quot;">​</a></h2><p>Image input (vision) and structured output (JSON mode / tool calling) are designed into the wire format and planned shortly after v0.1. The <code>WingMessage</code> type already reserves <code>parts</code> for this.</p><hr>',11)])])}const v=a(o,[["render",l]]);export{u as __pageData,v as default};
